package com.courseplanner.ui;

import com.courseplanner.model.*;import com.courseplanner.repository.CourseRepository;import com.courseplanner.service.*;import com.courseplanner.util.SampleData;
import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.io.*;import java.nio.file.*;import java.sql.SQLException;import java.util.*;import java.util.List;

public class MainFrame extends JFrame {
 private final CourseService service=new CourseService(new CourseRepository()); private final CardLayout cards=new CardLayout();private final JPanel content=new JPanel(cards);private final JLabel status=new JLabel("Ready");private final GraphPanel graph=new GraphPanel();private List<Course> courses=new ArrayList<>();private Map<String,Set<String>> prereqs=new LinkedHashMap<>();private Map<String,ProgressStatus> progress=new HashMap<>();private JTable courseTable,progressTable;private DefaultTableModel courseModel,progressModel;private JPanel dashboard;private int defaultMaxCourses=5;private TableRowSorter<DefaultTableModel> courseSorter;private JComboBox<Course> pathFrom,pathTo;private JLabel pathResult;
 public MainFrame(){super("Course Prerequisite Planner");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1120,720));setSize(1280,800);setLocationRelativeTo(null);buildShell();refreshAll();}
 private void buildShell(){getContentPane().setLayout(new BorderLayout());JPanel nav=new JPanel();nav.setBackground(Theme.NAVY);nav.setPreferredSize(new Dimension(220,0));nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));JLabel brand=new JLabel("  COURSE PLANNER");brand.setForeground(Color.WHITE);brand.setFont(new Font("SansSerif",Font.BOLD,17));brand.setBorder(BorderFactory.createEmptyBorder(25,8,28,4));nav.add(brand);addNav(nav,"▦   Dashboard","dashboard");addNav(nav,"▤   Course Management","courses");addNav(nav,"◎   Prerequisite Graph","graph");addNav(nav,"▥   Semester Planner","planner");addNav(nav,"✓   Student Progress","progress");addNav(nav,"▧   Reports & Analytics","reports");addNav(nav,"⚙   Settings","settings");nav.add(Box.createVerticalGlue());JLabel foot=new JLabel("  JAVA • GRAPH DSA • SQLITE");foot.setForeground(new Color(170,190,215));foot.setFont(new Font("SansSerif",Font.PLAIN,10));foot.setBorder(BorderFactory.createEmptyBorder(15,5,20,5));nav.add(foot);getContentPane().add(nav,BorderLayout.WEST);
  content.add(buildDashboard(),"dashboard");content.add(buildCourses(),"courses");content.add(buildGraph(),"graph");content.add(buildPlanner(),"planner");content.add(buildProgress(),"progress");content.add(buildReports(),"reports");content.add(buildSettings(),"settings");JPanel right=new JPanel(new BorderLayout());right.setBackground(Theme.BG);right.add(content,BorderLayout.CENTER);status.setBorder(BorderFactory.createEmptyBorder(8,18,8,18));status.setForeground(Theme.MUTED);right.add(status,BorderLayout.SOUTH);getContentPane().add(right,BorderLayout.CENTER);
 }
 private void addNav(JPanel nav,String label,String key){JButton b=new JButton(label);b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(220,46));b.setForeground(new Color(226,234,246));b.setBackground(Theme.NAVY);b.setBorder(BorderFactory.createEmptyBorder(12,18,12,8));b.setFocusPainted(false);b.setFont(new Font("SansSerif",Font.PLAIN,13));b.addActionListener(e->{refreshAll();cards.show(content,key);});nav.add(b);}
 private JPanel page(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(0,18));p.setBackground(Theme.BG);p.setBorder(BorderFactory.createEmptyBorder(25,28,22,28));JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));JLabel t=new JLabel(title);t.setFont(new Font("SansSerif",Font.BOLD,25));t.setForeground(Theme.TEXT);JLabel s=new JLabel(subtitle);s.setFont(new Font("SansSerif",Font.PLAIN,13));s.setForeground(Theme.MUTED);h.add(t);h.add(Box.createVerticalStrut(5));h.add(s);p.add(h,BorderLayout.NORTH);return p;}
 private JPanel buildDashboard(){dashboard=page("Dashboard","Your academic roadmap at a glance");JPanel body=new JPanel(new BorderLayout(0,16));body.setOpaque(false);JPanel metrics=new JPanel(new GridLayout(1,4,12,0));metrics.setOpaque(false);for(String k:List.of("Total Courses","Completed","In Progress","Locked")){JPanel c=metric(k,"0");metrics.add(c);}body.add(metrics,BorderLayout.NORTH);JPanel lower=new JPanel(new GridLayout(1,2,14,0));lower.setOpaque(false);JPanel quick=whitePanel();quick.setLayout(new BoxLayout(quick,BoxLayout.Y_AXIS));quick.add(sectionTitle("Quick actions"));JButton a=Theme.button("Generate semester plan");a.setAlignmentX(LEFT_ALIGNMENT);a.addActionListener(e->generatePlanDialog());JButton b=Theme.button("Open prerequisite graph");b.setAlignmentX(LEFT_ALIGNMENT);b.addActionListener(e->{refreshAll();cards.show(content,"graph");});quick.add(Box.createVerticalStrut(14));quick.add(a);quick.add(Box.createVerticalStrut(10));quick.add(b);JPanel insight=whitePanel();insight.setLayout(new BoxLayout(insight,BoxLayout.Y_AXIS));insight.add(sectionTitle("Planning insight"));JLabel msg=new JLabel("Complete prerequisite courses to unlock advanced subjects.");msg.setForeground(Theme.MUTED);insight.add(Box.createVerticalStrut(14));insight.add(msg);lower.add(quick);lower.add(insight);body.add(lower,BorderLayout.CENTER);dashboard.add(body,BorderLayout.CENTER);return dashboard;}
 private JPanel metric(String label,String value){JPanel p=whitePanel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel v=new JLabel(value);v.setName("metric:"+label);v.setFont(new Font("SansSerif",Font.BOLD,28));v.setForeground(Theme.BLUE);JLabel l=new JLabel(label);l.setForeground(Theme.MUTED);p.add(v);p.add(Box.createVerticalStrut(6));p.add(l);return p;}
 private JPanel buildCourses(){JPanel p=page("Course Management","Create courses and connect prerequisite relationships");JPanel body=new JPanel(new BorderLayout(0,12));body.setOpaque(false);courseModel=new DefaultTableModel(new Object[]{"Course ID","Course Name","Credits","Description"},0){public boolean isCellEditable(int r,int c){return false;}};courseTable=new JTable(courseModel);styleTable(courseTable);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));actions.setOpaque(false);JButton add=Theme.button("+ Add course"),edit=Theme.button("Edit selected"),del=Theme.button("Delete selected"),link=Theme.button("Add prerequisite");JTextField search=new JTextField(16);search.setToolTipText("Search by course ID or name");add.addActionListener(e->courseDialog(null));edit.addActionListener(e->{int r=courseTable.getSelectedRow();if(r>=0)courseDialog(courses.get(courseTable.convertRowIndexToModel(r)));});del.addActionListener(e->deleteSelected());link.addActionListener(e->prerequisiteDialog());actions.add(add);actions.add(edit);actions.add(del);actions.add(link);actions.add(new JLabel("Search:"));actions.add(search);courseSorter=new TableRowSorter<>(courseModel);courseTable.setRowSorter(courseSorter);search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){private void filter(){String q=search.getText().trim();courseSorter.setRowFilter(q.isEmpty()?null:RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(q),0,1));}public void insertUpdate(javax.swing.event.DocumentEvent e){filter();}public void removeUpdate(javax.swing.event.DocumentEvent e){filter();}public void changedUpdate(javax.swing.event.DocumentEvent e){filter();}});body.add(actions,BorderLayout.NORTH);body.add(new JScrollPane(courseTable),BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);return p;}
 private JPanel buildGraph(){JPanel p=page("Prerequisite Graph","Explore directed course dependencies • Scroll to zoom • Drag to pan • Select a node to highlight links");JPanel body=new JPanel(new BorderLayout(0,10));body.setOpaque(false);JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JPanel legend=new JPanel(new FlowLayout(FlowLayout.LEFT,15,0));legend.setOpaque(false);legend.add(legendItem(Theme.GREEN,"Completed"));legend.add(legendItem(Theme.BLUE,"Enrolled"));legend.add(legendItem(new Color(55,125,220),"Available"));legend.add(legendItem(Theme.ORANGE,"Locked"));JPanel path=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0));path.setOpaque(false);pathFrom=new JComboBox<>();pathTo=new JComboBox<>();pathResult=new JLabel("Choose two courses to find the shortest dependency path.");pathResult.setForeground(Theme.MUTED);JButton find=Theme.button("Find shortest path");find.addActionListener(e->{try{Course a=(Course)pathFrom.getSelectedItem(),b=(Course)pathTo.getSelectedItem();if(a==null||b==null)return;List<String> result=new CourseGraph(courses.stream().map(Course::getId).toList(),prereqs).shortestPath(a.getId(),b.getId());graph.setHighlightedPath(result);pathResult.setText(result.isEmpty()?"No directed path found.":String.join(" → ",result));}catch(Exception ex){showError(ex);}});path.add(new JLabel("From"));path.add(pathFrom);path.add(new JLabel("To"));path.add(pathTo);path.add(find);path.add(pathResult);top.add(legend,BorderLayout.NORTH);top.add(path,BorderLayout.SOUTH);body.add(top,BorderLayout.NORTH);body.add(graph,BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);return p;}
 private JPanel legendItem(Color c,String s){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,5,0));p.setOpaque(false);JPanel dot=new JPanel();dot.setBackground(c);dot.setPreferredSize(new Dimension(12,12));p.add(dot);JLabel l=new JLabel(s);l.setForeground(Theme.MUTED);p.add(l);return p;}
 private JPanel buildPlanner(){JPanel p=page("Semester Planner","Generate a valid learning sequence from your prerequisite graph");JPanel body=new JPanel(new BorderLayout(0,12));body.setOpaque(false);JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.setOpaque(false);JButton gen=Theme.button("Generate plan"),export=Theme.button("Export plan CSV");gen.addActionListener(e->generatePlanDialog());export.addActionListener(e->exportPlan());top.add(gen);top.add(export);JTextArea out=new JTextArea();out.setEditable(false);out.setFont(new Font("Monospaced",Font.PLAIN,13));out.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));out.setBackground(Color.WHITE);out.setName("plan-output");body.add(top,BorderLayout.NORTH);body.add(new JScrollPane(out),BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);return p;}
 private JPanel buildProgress(){JPanel p=page("Student Progress","Update course completion and enrollment status");JPanel body=new JPanel(new BorderLayout(0,12));body.setOpaque(false);progressModel=new DefaultTableModel(new Object[]{"Course ID","Course","Status","Prerequisites"},0){public boolean isCellEditable(int r,int c){return false;}};progressTable=new JTable(progressModel);styleTable(progressTable);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);JButton update=Theme.button("Update status");update.addActionListener(e->updateProgress());actions.add(update);body.add(actions,BorderLayout.NORTH);body.add(new JScrollPane(progressTable),BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);return p;}
 private JPanel buildReports(){JPanel p=page("Reports & Analytics","Review graph health and export your academic plan");JPanel body=whitePanel();body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JButton check=Theme.button("Validate prerequisite graph"),export=Theme.button("Export all courses CSV");JTextArea report=new JTextArea(12,60);report.setEditable(false);report.setBackground(Color.WHITE);check.addActionListener(e->{try{CourseGraph g=new CourseGraph(courses.stream().map(Course::getId).toList(),prereqs);report.setText("Graph validation\n----------------\nCourses: "+courses.size()+"\nEdges: "+prereqs.values().stream().mapToInt(Set::size).sum()+"\nCycle detected: "+g.hasCycle()+"\nKahn topological order: "+(g.hasCycle()?"Not available":g.topologicalSort())+"\nDFS topological order: "+(g.hasCycle()?"Not available":g.topologicalSortDfs()));}catch(Exception ex){showError(ex);}});export.addActionListener(e->exportCourses());body.add(check);body.add(Box.createVerticalStrut(8));body.add(export);body.add(Box.createVerticalStrut(14));body.add(new JScrollPane(report));p.add(body,BorderLayout.CENTER);return p;}
 private JPanel buildSettings(){JPanel p=page("Settings","Configure default semester planning preferences");JPanel box=whitePanel();box.setLayout(new BoxLayout(box,BoxLayout.Y_AXIS));box.add(sectionTitle("Semester planning"));box.add(Box.createVerticalStrut(12));JPanel row=new JPanel(new FlowLayout(FlowLayout.LEFT));row.setOpaque(false);row.add(new JLabel("Maximum courses per semester:"));JSpinner limit=new JSpinner(new SpinnerNumberModel(defaultMaxCourses,1,12,1));row.add(limit);JButton save=Theme.button("Save settings");save.addActionListener(e->{defaultMaxCourses=(Integer)limit.getValue();info("Planning preference saved for this session.");});row.add(save);box.add(row);box.add(Box.createVerticalStrut(20));box.add(sectionTitle("Application information"));JLabel info=new JLabel("Course Prerequisite Planner • Java 17 • Swing • SQLite • Graph DSA");info.setForeground(Theme.MUTED);box.add(Box.createVerticalStrut(8));box.add(info);JLabel db=new JLabel("Database file: course_planner.db (application working directory)");db.setForeground(Theme.MUTED);box.add(Box.createVerticalStrut(6));box.add(db);p.add(box,BorderLayout.CENTER);return p;}
 private JPanel whitePanel(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(230,234,241)),BorderFactory.createEmptyBorder(18,18,18,18)));return p;}
 private JLabel sectionTitle(String s){JLabel l=new JLabel(s);l.setFont(new Font("SansSerif",Font.BOLD,16));l.setForeground(Theme.TEXT);return l;}
 private void styleTable(JTable t){t.setFont(new Font("SansSerif",Font.PLAIN,13));t.setForeground(Theme.TEXT);t.setGridColor(new Color(235,239,245));t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.getTableHeader().setFont(new Font("SansSerif",Font.BOLD,12));t.getTableHeader().setBackground(new Color(239,243,249));t.setFillsViewportHeight(true);}
 private void refreshAll(){try{courses=service.all();prereqs=service.prerequisites();progress=service.progress(1);if(courseModel!=null){courseModel.setRowCount(0);for(Course c:courses)courseModel.addRow(new Object[]{c.getId(),c.getName(),c.getCredits(),c.getDescription()});}if(progressModel!=null){progressModel.setRowCount(0);for(Course c:courses)progressModel.addRow(new Object[]{c.getId(),c.getName(),progress.getOrDefault(c.getId(),ProgressStatus.PENDING),String.join(", ",prereqs.getOrDefault(c.getId(),Set.of()))});}if(graph!=null)graph.setData(courses,prereqs,progress);if(pathFrom!=null){Object f=pathFrom.getSelectedItem(),t=pathTo.getSelectedItem();pathFrom.removeAllItems();pathTo.removeAllItems();for(Course c:courses){pathFrom.addItem(c);pathTo.addItem(c);}if(f instanceof Course fc)pathFrom.setSelectedItem(courses.stream().filter(x->x.getId().equals(fc.getId())).findFirst().orElse(null));if(t instanceof Course tc)pathTo.setSelectedItem(courses.stream().filter(x->x.getId().equals(tc.getId())).findFirst().orElse(null));}updateMetrics();status.setText("Connected to SQLite • "+courses.size()+" courses loaded");}catch(Exception ex){showError(ex);}}
 private void updateMetrics(){if(dashboard==null)return;int done=0,enrolled=0,locked=0;for(Course c:courses){ProgressStatus s=progress.getOrDefault(c.getId(),ProgressStatus.PENDING);if(s==ProgressStatus.COMPLETED)done++;else if(s==ProgressStatus.ENROLLED)enrolled++;else if(prereqs.getOrDefault(c.getId(),Set.of()).stream().anyMatch(x->progress.getOrDefault(x,ProgressStatus.PENDING)!=ProgressStatus.COMPLETED))locked++;}for(Component c:((JPanel)((JPanel)dashboard.getComponent(1)).getComponent(0)).getComponents()){if(c instanceof JPanel card){for(Component z:card.getComponents())if(z instanceof JLabel l&&l.getName()!=null&&l.getName().startsWith("metric:")){String k=l.getName().substring(7);l.setText(switch(k){case "Total Courses"->""+courses.size();case "Completed"->""+done;case "In Progress"->""+enrolled;default->""+locked;});}}}}
 private void courseDialog(Course old){JTextField id=new JTextField(old==null?"":old.getId()),name=new JTextField(old==null?"":old.getName()),credits=new JTextField(old==null?"3":""+old.getCredits()),desc=new JTextField(old==null?"":old.getDescription());if(old!=null)id.setEditable(false);JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel("Course ID"));form.add(id);form.add(new JLabel("Course name"));form.add(name);form.add(new JLabel("Credits (1–10)"));form.add(credits);form.add(new JLabel("Description"));form.add(desc);if(JOptionPane.showConfirmDialog(this,form,old==null?"Add course":"Edit course",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{service.save(new Course(id.getText(),name.getText(),Integer.parseInt(credits.getText()),desc.getText()));refreshAll();}catch(Exception ex){showError(ex);}}}
 private void deleteSelected(){int r=courseTable.getSelectedRow();if(r<0){info("Select a course first.");return;}String id=courses.get(courseTable.convertRowIndexToModel(r)).getId();if(JOptionPane.showConfirmDialog(this,"Delete "+id+" and its prerequisite links?","Confirm delete",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{service.delete(id);refreshAll();}catch(Exception ex){showError(ex);}}
 private void prerequisiteDialog(){if(courses.size()<2){info("Add at least two courses first.");return;}JComboBox<Course> target=new JComboBox<>(courses.toArray(Course[]::new)),pre=new JComboBox<>(courses.toArray(Course[]::new));JPanel f=new JPanel(new GridLayout(0,2,8,8));f.add(new JLabel("Course"));f.add(target);f.add(new JLabel("Must complete first"));f.add(pre);if(JOptionPane.showConfirmDialog(this,f,"Add prerequisite",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{service.addPrerequisite(((Course)target.getSelectedItem()).getId(),((Course)pre.getSelectedItem()).getId());refreshAll();}catch(Exception ex){showError(ex);}}
 private void updateProgress(){int r=progressTable.getSelectedRow();if(r<0){info("Select a course first.");return;}String id=(String)progressModel.getValueAt(r,0);ProgressStatus current=(ProgressStatus)progressModel.getValueAt(r,2);ProgressStatus next=(ProgressStatus)JOptionPane.showInputDialog(this,"Select status for "+id,"Update progress",JOptionPane.PLAIN_MESSAGE,null,ProgressStatus.values(),current);if(next!=null)try{service.setProgress(1,id,next);refreshAll();}catch(Exception ex){showError(ex);}}
 private void generatePlanDialog(){String v=JOptionPane.showInputDialog(this,"Maximum courses per semester:",String.valueOf(defaultMaxCourses));if(v==null)return;try{List<SemesterPlan> plans=service.plan(1,Integer.parseInt(v));StringBuilder sb=new StringBuilder("GENERATED SEMESTER PLAN\n=======================\n\n");for(SemesterPlan p:plans){sb.append("SEMESTER ").append(p.getSemester()).append("\n");for(Course c:p.getCourses())sb.append("  • ").append(c.getId()).append(" — ").append(c.getName()).append(" ( ").append(c.getCredits()).append(" credits )\n");sb.append('\n');}JTextArea out=findPlanOutput();if(out!=null)out.setText(sb.toString());cards.show(content,"planner");status.setText("Plan generated successfully");}catch(Exception ex){showError(ex);}}
 private JTextArea findPlanOutput(){for(Component c:content.getComponents())if(c instanceof JPanel p&&p.getComponentCount()>1){for(Component z:((JPanel)p.getComponent(1)).getComponents())if(z instanceof JScrollPane sp&&sp.getViewport().getView() instanceof JTextArea t)return t;}return null;}
 private void exportPlan(){JTextArea t=findPlanOutput();if(t==null||t.getText().isBlank()){info("Generate a semester plan first.");return;}saveText(t.getText(),"semester-plan.txt");}
 private void exportCourses(){StringBuilder b=new StringBuilder("course_id,name,credits,description\n");for(Course c:courses)b.append(csv(c.getId())).append(',').append(csv(c.getName())).append(',').append(c.getCredits()).append(',').append(csv(c.getDescription())).append('\n');saveText(b.toString(),"courses.csv");}
 private String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
 private void saveText(String text,String suggested){JFileChooser fc=new JFileChooser();fc.setSelectedFile(new File(suggested));if(fc.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{Files.writeString(fc.getSelectedFile().toPath(),text);info("Exported: "+fc.getSelectedFile());}catch(IOException ex){showError(ex);}}
 private void info(String s){JOptionPane.showMessageDialog(this,s,"Course Planner",JOptionPane.INFORMATION_MESSAGE);}private void showError(Throwable ex){JOptionPane.showMessageDialog(this,ex.getMessage()==null?ex.toString():ex.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}
}
